Definition tbyte (tbl : list (list Z)) (j : Z) : Z := nth (Z.to_nat (j mod 16)) (nth (Z.to_nat (j / 16)) tbl []) 0.

Definition RECS (n : nat) (tbl : list (list Z)) : Prop :=
  length tbl = n /\ Forall (fun rec => length rec = 16%nat /\ bytes_ok rec) tbl.

