Lemma splice_nth : forall o bs rec i d, (o + length bs <= length rec)%nat -> (i < length rec)%nat ->
  nth i (splice o bs rec) d = if (Nat.leb o i && Nat.ltb i (o + length bs))%bool then nth (i - o) bs d else nth i rec d.
Proof.
