Lemma mkzt_get : forall l k t q,
  tget q (mkzt l k t) = if (Nat.leb (Pos.to_nat k) (Pos.to_nat q) && Nat.ltb (Pos.to_nat q) (Pos.to_nat k + length l))%bool
                        then nth_error l (Pos.to_nat q - Pos.to_nat k) else tget q t.
Proof.
