Lemma sim_branch : forall c rs1 rs2 imm w pc m tbl st' regs M rom,
  fetch_word segs (Z_to_bv 64 pc) = Some w -> is_ecall w = false -> decode_any w = Some (Branch c rs1 rs2 imm, 4) ->
